import{_ as i,l as n,o as e,c as o,v as t,p as s,x as r,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"蝶式与日历无套利","description":"","frontmatter":{"title":"蝶式与日历无套利","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/butterfly-calendar-arb.md","filePath":"quant/butterfly-calendar-arb.md","lastUpdated":1789023840000}'),E={name:"quant/butterfly-calendar-arb.md"};function m(u,a,c,B,A,_){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="蝶式与日历无套利" tabindex="-1">蝶式与日历无套利 <a class="header-anchor" href="#蝶式与日历无套利" aria-label="Permalink to &quot;蝶式与日历无套利&quot;">​</a></h1><div class="epigraph"><p>到期支付对执行价凸，故看涨价格必须对 $K$ 凸；更长到期的看涨不能系统性更便宜，否则日历价差送钱。这两条静态约束先于任何波动率模型。</p><footer>—— Breeden and Litzenberger, Journal of Business, 1978；曲面叙述见 Gatheral, The Volatility Surface, 2006</footer></div><p>期权做市的第一张风控表不是 <a href="/quant/heston">Heston</a> 参数，而是自己的报价能否被三档执行价或两个到期的静态组合锁死。蝶式价差检验凸性，日历价差检验期限。它们不依赖复制论证、不依赖连续对冲，只依赖欧式收益的定义与货币的时间价值。Gatheral 把这些不等式翻译成对隐含波动率曲面的语言，使交易员能在 \\(\\sigma_{\\mathrm{imp}}\\) 坐标上监控。本篇写可交易的套利组合、与密度的对应、以及和 <a href="/quant/arb-free-iv">无套利插值</a>、<a href="/quant/svi-ssvi">SVI / SSVI</a> 的分工；<a href="/quant/vol-skew">Skew</a> 写形状从哪来，这里写形状不能越过哪条线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧式看涨到期支付 \\((S_T-K)^+\\) 作为 \\(K\\) 的函数是凸的、递减的。取期望与折现不破坏凸性，故 \\(C(K,T)=e^{-rT}\\mathbb{E}[(S_T-K)^+]\\) 对 \\(K\\) 凸。离散市场上取三档 \\(K-\\Delta K\\)、\\(K\\)、\\(K+\\Delta K\\)，凸性变成蝶式</p> \\[C(K-\\Delta K)-2C(K)+C(K+\\Delta K)\\ge 0 \\]<p>（等间距时；不等间距要按杠杆加权）。左端除以 \\((\\Delta K)^2\\) 是密度的离散代理：Breeden–Litzenberger 说 \\(\\partial^2 C/\\partial K^2=e^{-rT}p^{\\mathbb{Q}}(K)\\)。负蝶式等于负密度，静态套利是买两翼、卖中间（或相反，视符号），持有到期，收益非负且在某些路径严格为正。</p><p>日历更精妙。简单的「\\(T_2\\gt T_1\\) 则 \\(C(K,T_2)\\ge C(K,T_1)\\)」在有利率、股息、且执行价按即期而非远期对齐时不必成立。无套利的干净形式是对未折现期望或对总方差：在利率股息处理正确后，同一远期货币性上，更长到期的看涨不应更便宜到可被日历价差锁定。问题是把教科书连续不等式，收成带买卖价差、美式溢价与期货乘数的可执行扫描。</p><h3 id="蝶式是密度-不是「弯曲交易」的别名" tabindex="-1">蝶式是密度，不是「弯曲交易」的别名 <a class="header-anchor" href="#蝶式是密度-不是「弯曲交易」的别名" aria-label="Permalink to &quot;蝶式是密度，不是「弯曲交易」的别名&quot;">​</a></h3><p>交易员口语里的「买蝶式」常指做多凸性、赌实现波动落在执行价附近。那是波动观点。无套利扫描里的蝶式是检验报价表内部是否自洽，不表达对实现波动的看法。一张负蝶式可以在隐含波动看起来「光滑」时出现——因为光滑的 \\(\\sigma_{\\mathrm{imp}}(K)\\) 不保证 \\(C(K)\\) 凸。这正是必须在价格空间扫描、而不能只在波动率图上目测的原因。</p><p><span class="marginnote">等间距蝶式的系数是 \\(1,-2,1\\)。执行价网格不规则时，要用二阶差商的正确权重，否则会把网格伪影报成套利。外汇 Delta 网格映射到 \\(K\\) 后几乎从不等距。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>蝶式扫描。</strong> 对每个到期、每一组相邻虚值报价（经平价转到同一侧），计算加权二阶差分，与买卖价差比较。只有当套利收益在穿过价差、手续费、保证金之后仍为正，才称为可执行。深度实值看涨的凸性检验无信息：价格贴齐远期，数值差分被最小报价单位主导。应在虚值端工作，或用看跌。</p><p><strong>日历扫描。</strong> 对相近货币性 \\(k=\\ln(K/F_T)\\)（注意两个到期的远期不同，应对齐 \\(k\\) 而不是对齐名义 \\(K\\)），比较未折现看涨或比较总方差 \\(w(k,T)\\)。若 \\(w(k,T_2)\\lt w(k,T_1)\\)，存在日历套利的候选。执行时用日历价差：买长到期、卖短到期，并处理股息与利率，使组合在短到期时不因提前行权或期货交割而破裂。股票美式看跌的日历不能当欧式扫。</p><p><strong>从扫描到曲面修补。</strong> 发现违规则回到插值层：放宽穿过脏点的要求、改用凸回归、或对 SVI 参数加 \\(b(1+|\\rho|)\\) 一类翼部约束。不要在违例的三档上人为「微调一个波动率点」却不管邻档——凸性是全局的，局部修补会在下一档再破。</p><h3 id="与模型希腊字母的关系" tabindex="-1">与模型希腊字母的关系 <a class="header-anchor" href="#与模型希腊字母的关系" aria-label="Permalink to &quot;与模型希腊字母的关系&quot;">​</a></h3><p>静态套利成立时，任何定价模型——包括校准得再好的 Heston 或 SABR——若仍复制那张违例曲面，模型价格也可被同一蝶式收取。这不是 <a href="/quant/greeks-hedge">Delta / Gamma / Vega 对冲</a> 能对冲掉的：对冲假设你按模型中间价成交，而套利者按你的违例报价成交。做市系统应在希腊字母之前跑静态扫描。反过来，曲面无静态套利并不表示 Heston 的 \\(\\rho\\) 对、也不表示 SABR Delta 与市场 sticky 一致；那是动态问题。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>蝶式把三档香草合成一个近似的 Arrow–Debreu 证券：到期时 \\(S_T\\) 落在中间执行价附近则支付为正，落在两翼之外为零（离散近似下为三角帽）。市价为负意味着市场对某一区间卖出了负的状态价格，现金机器出现。日历价差合成的是「多等一段时间」的凸性：在没有股息奇异、利率处理正确时，时间不能使欧式看涨变便宜。违例意味着折现、远期或美式溢价没从报价里剥干净，或者中间价不可成交。</p><p>隐含波动率语言里，过陡的翼会破坏 Lee 矩，等价于远处蝶式出问题；期限结构倒挂会破坏总方差递增。SVI 的参数约束与 SSVI 的 \\(\\theta_t\\) 递增，都是为了在参数空间里提前满足这些不等式，而不是事后用扫描去撞。扫描仍不可省，因为参数化只覆盖你选用的那一族形状。</p><h3 id="可执行性-价差、钉住与提前行权" tabindex="-1">可执行性：价差、钉住与提前行权 <a class="header-anchor" href="#可执行性-价差、钉住与提前行权" aria-label="Permalink to &quot;可执行性：价差、钉住与提前行权&quot;">​</a></h3><p>理论蝶式忽略买卖价差。翼部价差宽时，中间价负蝶式在卖出中间、买入两翼之后可能翻负变正——即不可执行。报告「无套利违约次数」必须声明是否穿透价差。到期日附近还要叠加 <a href="/quant/pin-risk">Pin risk</a>：蝶式的中间腿可能被钉住，对冲与行权决策把静态收益变成隔夜缺口。美式提前行权使「持有到期」的套利证明失效，必须改用欧式上市合约或先剥提前行权溢价。</p><p><span class="marginnote">把日历套利理解成「短到期隐含波动必须低于长到期」是错的。短端可以更高，\\(\\sigma_{\\mathrm{imp}}\\) 的期限结构倒挂很常见；约束的是总方差 \\(w=\\sigma^2 T\\) 以及经远期对齐后的价格，不是 \\(\\sigma\\) 本身单调。</span></p>',23)),(e(),s(d,null,{default:r(()=>[p(l,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20Grid%5B%22%E6%B8%85%E6%B4%97%E5%90%8E%E7%9A%84%E6%AC%A7%E5%BC%8F%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20BF%5B%22%E5%8A%A0%E6%9D%83%E8%9D%B6%E5%BC%8F%20%E2%89%A5%200%22%5D%0A%20%20Grid%20--%3E%20Cal%5B%22%E5%AF%B9%E9%BD%90%20k%20%E7%9A%84%E6%97%A5%E5%8E%86%20%2F%20%E6%80%BB%E6%96%B9%E5%B7%AE%E9%80%92%E5%A2%9E%22%5D%0A%20%20BF%20--%3E%20Dens%5B%22%E7%A6%BB%E6%95%A3%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%E5%AF%86%E5%BA%A6%22%5D%0A%20%20Cal%20--%3E%20W%5B%22w(k%2CT)%20%E6%9C%9F%E9%99%90%22%5D%0A%20%20Dens%20--%3E%20Patch%5B%22%E5%9B%9E%E5%86%99%E6%8F%92%E5%80%BC%E6%88%96%20SVI%20%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20W%20--%3E%20Patch%0A%20%20Patch%20--%3E%20Book%5B%22%E5%8F%AF%E5%8F%91%E5%B8%83%E6%9B%B2%E9%9D%A2%22%5D%0A%20%20Book%20--%3E%20Grk%5B%22%E5%86%8D%E7%AE%97%20Delta%20Vega%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>离散执行价使密度只在格子上有定义；格子之间的负密度可以被参数化藏住，也可以被样条制造出来。扫描粒度决定你看见多少。跨交易所、跨结算（期货期权对现货期权）的「蝶式」含基差，不是纯凸性。有红利的股票在除息附近，欧式看涨的日历会受分红影响，必须用带分红的无套利界，而不是零利率口诀。</p><p>Heston 作为扩散，理论价格满足这些不等式；校准残差若用插值补回市场点，补丁可能再引入静态套利——这是「模型 + 残差表面」管道的已知裂缝，应在残差层也做凸性约束。SABR 的 Hagan 展开在翼部可以破无套利，那是近似公式的问题，不是蝶式定义的问题；应用数值 SABR 或切断翼部。Gatheral（2006）系统整理了这些约束，并不是 1973 年 Black–Scholes 的推论：常数 \\(\\sigma\\) 的世界里蝶式自动满足，正是因为对数正态密度为正。</p><p><span class="marginnote">静态无套利是当日报价表的性质。明日曲面如何跳、隔夜是否缺口，属于动态与跳跃风险，要用 Vega 限额与 <a href="/quant/overnight-gap-hedge">隔夜跳空对冲</a>，不能靠蝶式扫描保证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蝶式非负 \\(\\Leftrightarrow\\) 离散凸性 \\(\\Leftrightarrow\\) 风险中性密度非负；日历约束应对齐远期货币性并看总方差，而非 \\(\\sigma_{\\mathrm{imp}}\\) 单调。</li><li>检验必须在价格空间做，并扣除买卖价差；光滑的隐含波动曲线可以仍破凸。</li><li>发现违例应回写插值或 SVI/SSVI 约束，而不是先改希腊字母。</li><li>静态套利先于 Heston / SABR 动态；模型拟合不能自动治愈脏报价。</li><li>美式、分红、不等距网格与钉住风险限制「持有到期」证明的可执行性。</li><li>出处：Breeden and Litzenberger, <em>Journal of Business</em>, 1978；Gatheral, <em>The Volatility Surface</em>, 2006；Lee 矩公式，2004；SSVI 见 Gatheral and Jacquier, 2014。</li></ul>',6))])}const g=i(E,[["render",m]]);export{b as __pageData,g as default};
